{"FACILITYID":"162423","projid":"TRANS20119.1","projname":"Downtown Core Complete Streets (Brorein St from Ashley Dr to Morgan St)","projdesc":"This project provides for multimodal and safety improvements.
General maintenance and Complete Streets improvements to several streets and incorporated in this project in the Downtown Core: Brorein St from Ashley Dr to Morgan St.
As part of the project, these roadways will be resurfaced to remove deficiencies and provide a newly finished driving surface.  This project will also include multimodal improvements to make these corridors safer for all users in accordance with the City’s Vision Zero initiative.
• Parking Protected Buffered Bike Lanes with conflict markings to allow for safer cycling;
• Pedestrian Bulb-outs to shorten pedestrian crossing distances;
• Enhanced Crosswalks to provide pedestrians with more visibility;
• Traffic Calming features to control speeds and reduce the likelihood of fatal crashes;
• Reconstructed Curb Ramps to provide ease of use and accessibility to people with disabilities.","rationale":"Complete Streets & Safety Improvements - C.W.Roberts resurfacing","projtype":"Transportation","safety":"Yes","mandate":"No","repair":"No","replace":"No","expand":"No","efficient":"No","fiscalyr":"2025","fundsource":"Local Option Gas Tax","planstart":1745798400000,"planend":1748563200000,"estcost":1900000,"funded":"Yes","projphase":"P5: Closeout","actstart":1745798400000,"actend":1748563200000,"actcost":0,"status":"Closeout","docpath":null,"CreationDate":1610668412000,"EditDate":1750777395000,"MultiYear":"Yes","NumVotes":null,"ShowPublic":"Yes","EBO":null,"JobsCreated":null,"Neighborhood":"Tampa Downtown Partnership","Council":"5","EBOAttained":null,"ContractNumber":"1001541","ActivityStatus":null,"ProjectSiteURL":"https://www.tampa.gov/project/trans201191","RelatedProject":null,"MapScale":6000,"WMBESLBE":null,"ORACLEID":null,"EBUILDERID":null,"COMPROCUREMENT":null,"WATER":null,"WASTEWATER":null,"STORMWATER":null,"TRANSPORTATION":"Contractor Resurfacing","OBJECTID":627,"GlobalID":"{03EC0291-9384-4123-BAAC-F7764F2B153E}","ProjectNumerical":1001541,"Shape__Length":867.0016308863998}

